CREATE TABLE credit_grants(id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY,user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL,credits BIGINT NOT NULL,reason TEXT NOT NULL,actor VARCHAR(191) NOT NULL,request_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL UNIQUE,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
